export async function listActivityForExport(
  actor: Actor,
  input: Pick<ExportActivityInput, "orgId" | "since" | "until">,
): Promise<readonly ActivityEvent[]> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "activity:export", activityResource(input.orgId));

  return activityRepo.listAllActivity({
    orgId: input.orgId,
    since: input.since,
    until: input.until,
  });
}

/**
 * CSV (or JSON) export of the audit log. Gated twice: on `activity:export`
 * for the role, and on the `csv_export` flag for the plan.
 */
export async function exportActivity(
  actor: Actor,
  input: ExportActivityInput,
): Promise<string> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "activity:export", activityResource(input.orgId));

  const org = await orgRepo.findOrgById(input.orgId);
  const flagEnabled = isEnabled("csv_export", {
    orgId: input.orgId,
    userId: actor.userId,
    plan: org?.plan ?? "free",
    role: actor.role,
    overrides: org?.settings.enabledFlagOverrides,
  });

  if (input.format === "csv" && !flagEnabled) {
    throw new Error("CSV export is not included in this plan");
  }

  const events = await listActivityForExport(actor, input);

  if (input.format === "json") {
    return JSON.stringify(events, null, 2);
  }

  return toCsv(
    events.map((event) => ({
      occurredAt: event.occurredAt,
      action: event.action,
      actorId: event.actorId,
      subjectKind: event.subjectKind,
      subjectId: event.subjectId,
      summary: event.summary,
    })),
    [...EXPORT_COLUMNS],
  );
}

/**
 * The project a comment belongs to is the project of the issue it sits on.
 * Comment events carry it in the payload; the lookup only covers a payload
 * that predates that field.
 */
async function projectOfComment(
  orgId: OrgId,
  issueId: IssueId,
  known: ProjectId | undefined,
): Promise<ProjectId | null> {
  if (known) return known;
  const issue = await issueRepo.findIssueById(orgId, issueId);
  return issue?.projectId ?? null;
}

