/**
 * The audit trail end to end: real services publish, the activity listeners
 * record, the feed and the export read back.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { emit } from "@/lib/event-bus";
import * as activityRepo from "@/server/repositories/activity-repository";
import {
  exportActivity,
  listActivity,
  record,
  registerActivityListeners,
} from "@/server/services/activity-service";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { ActivityFilterInput } from "@/schemas/activity";
import type { ActivityEvent } from "@/types/activity";
import type { IsoTimestamp } from "@/types/common";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let detach: Unsubscribe;

const stamp = (value: string) => value as IsoTimestamp;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("audit", "growth");
  detach = registerActivityListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

async function feed(
  filter: Partial<ActivityFilterInput> = {},
): Promise<readonly ActivityEvent[]> {
  const page = await listActivity(tenant.actors.admin, {
    orgId: tenant.org.id,
    limit: 100,
    cursor: null,
    ...filter,
  });
  return page.items;
}

describe("audit trail", () => {
  it("files every project-scoped action under its project, naming who acted", async () => {
    const project = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Scoped",
      slug: "scoped",
      key: "SCO",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, project.id, { title: "Inside" }),
    );
    await projectService.updateProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: project.id,
      name: "Scoped renamed",
    });
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      status: "in_progress",
    });
    await issueService.assignIssue(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.member,
    });
    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "first",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.updateComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: comment.id,
      body: "edited",
    });
    await commentService.deleteComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: comment.id,
    });
    await issueService.archiveIssue(tenant.actors.admin, tenant.org.id, issue.id);
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: project.id,
      archiveIssues: false,
    });
    await projectService.restoreProject(tenant.actors.admin, tenant.org.id, project.id);

    const inProject = await feed({ projectId: project.id });
    expect(inProject.map((event) => event.action).sort()).toEqual(
      [
        "comment.created",
        "comment.deleted",
        "comment.updated",
        "issue.archived",
        "issue.assigned",
        "issue.created",
        "issue.status_changed",
        "project.archived",
        "project.created",
        "project.restored",
        "project.updated",
      ].sort(),
    );

    const byAction = (action: string) => inProject.filter((event) => event.action === action);
    expect(byAction("issue.assigned")[0]?.actorId).toBe(tenant.userIds.admin);
    expect(byAction("issue.status_changed")[0]?.metadata).toEqual({
      from: "backlog",
      to: "in_progress",
    });
    expect(byAction("comment.deleted")[0]?.actorId).toBe(tenant.userIds.member);
  });

  it("records member and plan-level actions exactly once", async () => {
    const before = await feed();
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: (await memberRepoMemberId("viewer")),
      role: "member",
    });
    const after = await feed();
    expect(after.length).toBe(before.length + 1);
    expect(after[0]).toMatchObject({
      action: "member.role_changed",
      actorId: tenant.userIds.owner,
      metadata: { from: "viewer", to: "member" },
    });
  });

  it("keeps the time the action happened, not the time it was written", async () => {
    const happened = stamp("2020-05-05T05:05:05.005Z");
    await emit("billing.plan_changed", {
      orgId: tenant.org.id,
      actorId: null,
      occurredAt: happened,
      from: "growth",
      to: "free",
    });

    const found = await feed({ since: happened, until: happened });
    expect(found).toHaveLength(1);
    expect(found[0]?.occurredAt).toBe(happened);
  });

  it("treats both ends of a range as inclusive and refuses a reversed one", async () => {
    const early = stamp("2021-01-01T00:00:00.000Z");
    const late = stamp("2021-01-01T00:00:01.000Z");
    for (const at of [early, late]) {
      await record(tenant.org.id, "organization.updated", {
        actorId: tenant.userIds.owner,
        occurredAt: at,
        subjectKind: "organization",
        subjectId: tenant.org.id,
        projectId: null,
        summary: "settings",
      });
    }

    expect(await feed({ since: early, until: late })).toHaveLength(2);
    expect(await feed({ since: late, until: late })).toHaveLength(1);
    // A range written without milliseconds still lines up with stored rows.
    expect(
      await feed({ since: stamp("2021-01-01T00:00:00Z"), until: stamp("2021-01-01T00:00:00Z") }),
    ).toHaveLength(1);
    await expect(feed({ since: late, until: early })).rejects.toThrow();
    await expect(
      exportActivity(tenant.actors.admin, {
        orgId: tenant.org.id,
        since: late,
        until: early,
        format: "json",
      }),
    ).rejects.toThrow();
  });

  it("exports every entry in range, newest first, with details, for this workspace only", async () => {
    const other = await createTenant("audit-other", "growth");
    const base = Date.parse("2022-03-03T00:00:00.000Z");
    const total = 250;

    for (let index = 0; index < total; index += 1) {
      await record(tenant.org.id, "issue.status_changed", {
        actorId: tenant.userIds.member,
        // Every third entry shares its instant with the previous one.
        occurredAt: new Date(base + Math.floor(index / 3) * 1000).toISOString(),
        subjectKind: "issue",
        subjectId: `issue-${index}`,
        projectId: null,
        summary: `entry ${index}`,
        metadata: { from: "backlog", to: "done", index },
      });
    }
    await record(other.org.id, "issue.status_changed", {
      actorId: other.userIds.member,
      occurredAt: new Date(base).toISOString(),
      subjectKind: "issue",
      subjectId: "foreign",
      projectId: null,
      summary: "foreign entry",
    });

    const range = {
      orgId: tenant.org.id,
      since: stamp(new Date(base).toISOString()),
      until: stamp(new Date(base + 100 * 1000).toISOString()),
    };

    const json = JSON.parse(
      await exportActivity(tenant.actors.admin, { ...range, format: "json" }),
    ) as ActivityEvent[];
    expect(json).toHaveLength(total);
    expect(new Set(json.map((event) => event.id)).size).toBe(total);
    expect(json.every((event) => event.orgId === tenant.org.id)).toBe(true);
    expect(json[0]?.metadata).toMatchObject({ from: "backlog", to: "done" });
    const times = json.map((event) => event.occurredAt);
    expect([...times].sort().reverse()).toEqual(times);

    const csv = await exportActivity(tenant.actors.admin, { ...range, format: "csv" });
    expect(csv.split("\r\n")).toHaveLength(total + 1);
  });

  it("stores the details it is given", async () => {
    const row = await activityRepo.insertActivity({
      orgId: tenant.org.id,
      action: "issue.status_changed",
      actorId: null,
      subjectKind: "issue",
      subjectId: "detail",
      projectId: null,
      summary: "detail",
      metadata: { from: "todo", to: "done" },
      occurredAt: stamp("2023-01-01T00:00:00.000Z"),
    });
    expect(row.metadata).toEqual({ from: "todo", to: "done" });
  });
});

async function memberRepoMemberId(role: "viewer"): Promise<never> {
  const { findMember } = await import("@/server/repositories/member-repository");
  const member = await findMember(tenant.org.id, tenant.userIds[role]);
  return member?.id as never;
}
